#!/usr/bin/env python3
"""Optional PDF engine for Moms Finance: python3 pdf_reportlab.py in.json out.pdf (needs reportlab). Called by app/pdf.php with a fixed argument list, no shell."""
import json, sys
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image

d = json.load(open(sys.argv[1], encoding='utf-8'))
base, bold = 'Helvetica', 'Helvetica-Bold'
try:
    pdfmetrics.registerFont(TTFont('DV', d['font'])); pdfmetrics.registerFont(TTFont('DVB', d['font_bold'])); base, bold = 'DV', 'DVB'
except Exception:
    pass
GREEN = colors.HexColor('#0b6b4d'); INK = colors.HexColor('#1e2823'); MUTE = colors.HexColor('#5f6e66'); SOFT = colors.HexColor('#f3f6f3')
title = 'Spending analysis' if d.get('kind') == 'analysis' else 'Monthly report'
def st(n, **k):
    return ParagraphStyle(n, fontName=k.pop('fontName', base), textColor=k.pop('textColor', INK), **k)
H2 = st('h2', fontName=bold, fontSize=12, textColor=GREEN, spaceBefore=10, spaceAfter=4); P = st('p', fontSize=9, leading=12, textColor=MUTE)

def page(c, doc):
    first = doc.page == 1; band = (30 if first else 14) * mm
    c.saveState(); c.setFillColor(GREEN); c.rect(0, A4[1] - band, A4[0], band, stroke=0, fill=1)
    c.setFillColor(colors.white); c.setFont(bold, 17 if first else 10); c.drawString(14 * mm, A4[1] - (14 if first else 9) * mm, d['app'])
    c.setFont(base, 10 if first else 8); c.drawRightString(A4[0] - 14 * mm, A4[1] - (13 if first else 9) * mm, title)
    if first:
        c.setFont(base, 9); c.drawRightString(A4[0] - 14 * mm, A4[1] - 20 * mm, '%s · prepared for %s · %s' % (d['month_label'], d['user'], d['generated']))
    c.setFillColor(MUTE); c.setFont(base, 8); c.drawString(14 * mm, 8 * mm, 'Generated by %s' % d['app']); c.drawRightString(A4[0] - 14 * mm, 8 * mm, 'Page %d' % doc.page); c.restoreState()

def table(head, rows, widths, empty):
    if not rows:
        return Paragraph(empty, P)
    t = Table([head] + rows, colWidths=[w * mm for w in widths], repeatRows=1)
    t.setStyle(TableStyle([('FONTNAME', (0, 0), (-1, 0), bold), ('FONTNAME', (0, 1), (-1, -1), base), ('FONTSIZE', (0, 0), (-1, -1), 8.5), ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#ecf1ed')),
        ('TEXTCOLOR', (0, 0), (-1, 0), MUTE), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#fafbfa')]), ('ALIGN', (1, 0), (-1, -1), 'RIGHT'), ('TOPPADDING', (0, 0), (-1, -1), 3), ('BOTTOMPADDING', (0, 0), (-1, -1), 3)]))
    return t

s = d['sum']; story = [Spacer(1, 22 * mm)]
tiles = [('Income received', s['fmt_income']), ('Total expenses', s['fmt_expenses']), ('Saved this month', s['fmt_net']), ('Savings rate', '–' if s['rate'] is None else '%d%%' % s['rate'])]
tt = Table([[Paragraph(a, st('a', fontSize=8, textColor=MUTE)) for a, b in tiles], [Paragraph(b, st('b', fontName=bold, fontSize=13)) for a, b in tiles]], colWidths=[45.5 * mm] * 4)
tt.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), SOFT), ('LINEBEFORE', (0, 0), (0, -1), 3, GREEN), ('LEFTPADDING', (0, 0), (-1, -1), 8), ('TOPPADDING', (0, 0), (-1, -1), 6), ('BOTTOMPADDING', (0, 0), (-1, -1), 6)]))
story += [tt, Spacer(1, 4), Paragraph('Balance across accounts: %s · reserved for goals: %s' % (d['fmt']['cash'], d['fmt']['reserved']), P)]
if d.get('kind') == 'analysis' and 'line' in d['charts']:
    story += [Paragraph('Spending through the month (running total)', H2), Image(d['charts']['line'], 182 * mm, 70 * mm)]
story += [Paragraph('Income and expenses, last six months', H2), Image(d['charts']['bars'], 182 * mm, 79 * mm)]
if 'pie' in d['charts']:
    story += [Paragraph('Where the money went', H2), Image(d['charts']['pie'], 70 * mm, 70 * mm)]
story += [Paragraph('Spending by category', H2), table(['Category', 'This month', 'Share', d['sum']['prev_label'], 'Change'], [[c['name'], c['fmt'], '%s%%' % c['share'], c['fmt_prev'], '–' if c['change'] is None else '%+d%%' % c['change']] for c in d['categories']], [70, 36, 22, 32, 22], 'No expenses this month.'),
    Paragraph('Top payees', H2), table(['Paid to', 'Payments', 'Total'], [[x['name'], str(x['count']), x['fmt']] for x in d['payees']], [90, 30, 62], 'No payments yet.'),
    Paragraph('Savings goals', H2), table(['Goal', 'Saved', 'Progress'], [[g['name'], g['fmt'], '%d%%' % g['percent']] for g in d['goals']], [80, 70, 32], 'No goals yet.'),
    Paragraph('Upcoming bills', H2), table(['Bill', 'Due', 'Amount'], [[b['name'], b['due_fmt'] + (' (overdue)' if b['overdue'] else ''), b['fmt']] for b in d['bills']], [90, 40, 52], 'Nothing due soon.')]
SimpleDocTemplate(sys.argv[2], pagesize=A4, leftMargin=14 * mm, rightMargin=14 * mm, topMargin=16 * mm, bottomMargin=16 * mm, title=title, author=d['app']).build(story, onFirstPage=page, onLaterPages=page)
